        /// <summary>All catalog entries for one job, ordered by level then name.</summary>
        /// <param name="jobId">Job id (1-22).</param>
        /// <returns>Entries learned by that job.</returns>
        public static IEnumerable<AbilityCatalogEntry> ForJob(int jobId)
        {
            return All.Where(e => e.JobId == jobId).OrderBy(e => e.Level).ThenBy(e => e.Name);
        }
